examples.template:
NavigationSuiteScaffold(
    navigationSuiteItems = {
        destinations.forEachIndexed { index, (name, icon) ->
            item(
                selected = current == index,
                onClick = { current = index },
                icon = { Icon(icon, contentDescription = null) },
                label = { Text(name) },
                badge = if (index == 1) { { Badge { Text("{{nav.1.badge|raw}}") } } } else null,
            )
        }
    },
    modifier = Modifier.height(MonarchTheme.spacing.space24 * 4),
    layoutType = NavigationSuiteType.NavigationRail,
) {
    Column {
        Row(
            modifier = Modifier.fillMaxWidth().padding(MonarchTheme.spacing.space3),
            verticalAlignment = Alignment.CenterVertically,
        ) {
            MonarchText(text = {{product}}, style = MonarchTextStyle.BodyStrong, modifier = Modifier.weight(1f))
            MonarchAvatar(image = null, name = {{account.name}}, size = MonarchAvatarSize.Sm)
        }
        MonarchDivider()
        MonarchText(text = {{header.title}}, style = MonarchTextStyle.Title)
        MonarchText(text = {{header.description}}, style = MonarchTextStyle.Caption)
        LazyColumn {
            items(listOf(
                {{conversations.0}},
                {{conversations.1}},
                {{conversations.2}},
                {{conversations.3}},
                {{conversations.4}},
                {{conversations.5}},
                {{conversations.6}},
                {{conversations.7}},
                {{conversations.8}},
                {{conversations.9}},
                {{conversations.10}},
                {{conversations.11}},
            )) { subject ->
                MonarchLink(text = subject, onClick = {}, variant = MonarchLinkVariant.Standalone)
            }
        }
    }
}

examples.setupTemplate:
var current by rememberSaveable { mutableIntStateOf(1) }
// "{{current}}" is the destination the web shell marks current.
val destinations = listOf(
    {{nav.0.label}} to SampleIcons.Home,
    {{nav.1.label}} to SampleIcons.Inbox,
    {{nav.2.label}} to SampleIcons.Calendar,
)

