                label = { Text(name) },
                badge = if (index == 1) { { Badge { Text("12") } } } else null,
            )
        }
    },
    modifier = Modifier.height(MonarchTheme.spacing.space24 * 4),
    layoutType = NavigationSuiteType.NavigationRail,
) {
    Column {
        Row(
            modifier = Modifier.fillMaxWidth().padding(MonarchTheme.spacing.space3),
            verticalAlignment = Alignment.CenterVertically,
        ) {
            MonarchText(text = "Acme Desk", style = MonarchTextStyle.BodyStrong, modifier = Modifier.weight(1f))
            MonarchAvatar(image = null, name = "Ada Lovelace", size = MonarchAvatarSize.Sm)
        }
        MonarchDivider()
        MonarchText(text = "Inbox", style = MonarchTextStyle.Title)
        MonarchText(text = "12 open conversations", style = MonarchTextStyle.Caption)
        LazyColumn {
            items(listOf(
                "Printer offline on floor 3",
                "Invoice shows the wrong address",
                "Reset two-factor for a new phone",
                "Export stops after page one",
                "Add a second admin",
                "Card declined at renewal",
                "Refund not received",
                "Change the billing contact",
                "Calendar invites arrive late",
                "Cannot upload files over 20 MB",
                "Move the workspace to the EU region",
                "Close the old London office account",
            )) { subject ->
                MonarchLink(text = subject, onClick = {}, variant = MonarchLinkVariant.Standalone)
            }
        }
    }
}

NavigationSuiteScaffold(
    navigationSuiteItems = {
        item(
            selected = true,
            onClick = {},
            icon = { Icon(SampleIcons.Pencil, contentDescription = null) },
            label = { Text("Notes") },
        )
    },
    modifier = Modifier.height(MonarchTheme.spacing.space24 * 3),
    layoutType = if (editing) NavigationSuiteType.None else adaptive,
) {
    MonarchButton(text = if (editing) "Done" else "Edit", onClick = { editing = !editing })
}
